import{_ as l,o as e,c as t,aw as o}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Gitflow","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/main/git/theory/gitflow.md","filePath":"wiki/dev-commit/main/git/theory/gitflow.md"}'),a={name:"wiki/dev-commit/main/git/theory/gitflow.md"};function r(d,i,s,n,f,u){return e(),t("div",null,[...i[0]||(i[0]=[o('<h1 id="gitflow" tabindex="-1">Gitflow <a class="header-anchor" href="#gitflow" aria-label="Permalink to &quot;Gitflow&quot;">​</a></h1><ul><li><strong>Gitflow</strong> - модуль управления ветками. Есть две основные ветки: master и develop</li><li><strong>gitflow-avh</strong> - инструмент для работы с Gitflow</li></ul><h2 id="ветки" tabindex="-1">Ветки <a class="header-anchor" href="#ветки" aria-label="Permalink to &quot;Ветки&quot;">​</a></h2><ul><li>master - содержится тот же код, что и в рабочей (продакт) версии проекта</li><li>release - подготовка к новому релизу проекта</li><li>beta - beta</li><li>develop - происходит вся работа</li></ul><hr><ul><li>feature - создаются в процессе работы над develop, их может быть неограниченное количество</li><li>improvement - улучшение</li><li>bug - исправление багов</li><li>bugfix - исправление багов</li><li>hotfix - срочное исправление багов, найденных, например, на продакте</li><li>fix - fix</li></ul><h2 id="рабочии-процесс-в-gitflow" tabindex="-1">Рабочий процесс в Gitflow <a class="header-anchor" href="#рабочии-процесс-в-gitflow" aria-label="Permalink to &quot;Рабочий процесс в Gitflow&quot;">​</a></h2><ol><li>Создается репозиторий</li><li>Репозиторий инициализируется</li><li>Начинается работа на ветке develop</li><li>Возникает необходимость опробовать новую штуку – создается feature-ветка и делаются коммиты</li><li>Закончив работу на feature-ветке, вы сливаете ее с develop</li><li>Если вы довольны текущей версией, но хотите продолжить работу, создается ветка release, куда перемещается текущая версия. Правка багов будет происходить на этой же ветке</li><li>Когда с веткой release покончено, время слить ее в master и продолжить работу с develop</li><li>Кроме того, этот момент можно отметить на master-ветке</li></ol><h2 id="codereview-github" tabindex="-1">Codereview GitHub <a class="header-anchor" href="#codereview-github" aria-label="Permalink to &quot;Codereview GitHub&quot;">​</a></h2><ol><li>Создать репозиторий</li><li>Основная ветка разработки &quot;dev&quot;</li><li>Под каждую задачу создается ветка от &quot;dev&quot;</li><li>Создание PR (Pool Request) для слития ветки задачи с веткой &quot;dev&quot;</li><li>Ссылка на PR руководителю</li><li>Если всё ок, слитие веток, если нет, то исправление замечания</li><li>Если несколько задач и несколько веток, то вливать нужно не ветки полностью а только отдельные коммиты</li></ol>',10)])])}const c=l(a,[["render",r]]);export{m as __pageData,c as default};
